"use client";
import { useEffect, useRef, useState } from "react";
import { ShaderSurface, type ShaderSurfaceOptions } from "./shader-surface";
export interface ImageDissolveScrollProps
  extends Pick<
    ShaderSurfaceOptions,
    | "children"
    | "className"
    | "style"
    | "height"
    | "alt"
    | "progress"
    | "background"
    | "maxDpr"
    | "onReady"
  > {
  image: string;
  noiseScale?: number;
  edgeColor?: string;
  edgeWidth?: number;
  onProgress?: (progress: number) => void;
}
/** Controlled noise dissolve, or a pinned window-scroll scene when progress is omitted. */
export function ImageDissolveScroll({
  progress,
  height = "var(--zeus-animation-height, 600px)",
  noiseScale = 4,
  edgeColor = "#ff9a43",
  edgeWidth = 1,
  onProgress,
  ...props
}: ImageDissolveScrollProps) {
  const root = useRef<HTMLDivElement>(null),
    scene = useRef<HTMLDivElement>(null);
  const [observed, setObserved] = useState(0);
  const callback = useRef(onProgress);
  callback.current = onProgress;
  useEffect(() => {
    if (progress !== undefined) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      const node = root.current,
        stage = scene.current;
      if (!node || !stage) return;
      const next = Math.min(
        1,
        Math.max(
          0,
          -node.getBoundingClientRect().top / Math.max(1, node.offsetHeight - stage.offsetHeight),
        ),
      );
      setObserved(next);
      callback.current?.(next);
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    const observer = new ResizeObserver(schedule);
    if (root.current) observer.observe(root.current);
    update();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
    };
  }, [progress]);
  return (
    <div
      ref={root}
      data-dissolve-scroll
      style={{
        width: "100%",
        height:
          progress === undefined
            ? `calc(${typeof height === "number" ? `${height}px` : height} * 2)`
            : height,
        position: "relative",
      }}
    >
      <div
        ref={scene}
        style={{ position: progress === undefined ? "sticky" : "relative", top: 0, height }}
      >
        <ShaderSurface
          kind="dissolve"
          height="100%"
          scale={noiseScale}
          intensity={edgeWidth}
          colors={[edgeColor]}
          progress={progress ?? observed}
          {...props}
        />
      </div>
    </div>
  );
}
